/* Selected-file operations, initech-7aou. The real face over a filesystem
 * mock, with fault injection. Prompt goldens are REAL WP 5.1 captures in
 * fixtures/iword-listfiles-ops (Reference PDF pp. 364-370). Safety assertions
 * are the PM's contract: protected files, failed copies and the active
 * document survive. No expectation is generated by the implementation. */
#include <dirent.h>
#include <sys/stat.h>
#include <errno.h>
#define IWORD_LF_OPS_MOCK
#define main old_face_main
#include "test_iword_face.c"
#undef main
#define F5 0x3F
#define ENTER VK_ENTER

static const char *grids;
#define budget (tbx_host.write_budget)
#define fail_read (tbx_host.file_error[TBX_FILE_READ])
#define fail_close (tbx_host.fail_close)
#define fail_close_handle (tbx_host.fail_close_handle)
#define fail_rename (tbx_host.file_error[TBX_FILE_RENAME])
static iw_ed_t document_before;
static int calls_named(const char *name) {
    int n=0;for(unsigned i=0;i<tbx_host.nops;i++)if(!strcmp(tbx_host.ops[i].name,name))n++;return n;
}
#define creates calls_named("tbx_file_create_new")
#define deletes calls_named("tbx_file_delete")
static int protected_calls(void) {
    int n=0;for(unsigned i=0;i<tbx_host.nops;i++) {
        const tbx_host_op_t *o=&tbx_host.ops[i];
        if((!strcmp(o->name,"tbx_file_delete")||!strcmp(o->name,"tbx_file_rename"))&&strstr(o->text,"LOCK.TXT"))n++;
    }return n;
}
#define protected_attempts protected_calls()

static void seed(const char *p,const char *s)
{ char hp[1024];host_name(p,hp);FILE *f=fopen(hp,"wb");if(!f){perror(hp);exit(2);}fwrite(s,1,strlen(s),f);fclose(f); }
static int content(const char *p,const char *s)
{ char hp[1024],b[128];host_name(p,hp);FILE *f=fopen(hp,"rb");if(!f)return 0;size_t n=fread(b,1,sizeof b,f);fclose(f);return n==strlen(s)&&!memcmp(b,s,n); }
static int exists(const char *p) { char hp[1024];struct stat s;host_name(p,hp);return !stat(hp,&s); }
static int prompt(const char *shot)
{
    char path[512],line[512];snprintf(path,sizeof path,"%s/%s.txt",grids,shot);FILE *f=fopen(path,"r");
    CHECK(f!=0,"ops-golden","real-WP grid readable");if(!f)return 0;int ok=0;
    while(fgets(line,sizeof line,f))if(!strncmp(line,"24|",3)){line[3+SCR_W]=0;ok=row_is(23,line+3);break;}
    if(!ok)fprintf(stderr,"  %s actual |%.76s|\n",shot,m_scr[23]);
    CHECK(ok,"ops-prompt",shot);
    /* Independently map the mint's selected filename to BLACK on GRAY,
     * bright white to bold, ordinary intensity to plain; cursor excluded.
     * These are the face's existing period colour/face adaptations. */
    int attrs = 0;
    while (fgets(line,sizeof line,f)) if (!strncmp(line,"24 ",3)) {
        char *p = line+3; attrs=1;
        while (*p && *p!='\n') {
            int a,b,used=0;unsigned fg,bg;
            if(sscanf(p,"%d-%d:%x/%x%n",&a,&b,&fg,&bg,&used)!=4 || !used){attrs=0;break;}
            for(int c=a;c<=b&&c<SCR_W;c++) if(!m_inv[23][c]&&m_scr[23][c]!=' ') {
                int band=bg==0xaaaaaau;
                if(m_col[23][c]!=(band?0x12:0x03) || (m_face[23][c]&1)!=(fg==0xffffffu&&!band)) attrs=0;
            }
            p+=used;while(*p==' ')p++;
        }
        break;
    }
    fclose(f);CHECK(attrs,"ops-prompt","mint filename band and bright/default choice cells");return ok&&attrs;
}
static void select_file(const char *name)
{ for(uint32_t i=0;i<g_lf_n;i++)if(!strcmp(g_lf_ent[i].name,name)){g_lf_sel=i+2;paint_all();return;} CHECK(0,"ops-select",name); }
static void active(void)
{ int same=g_ed.doc.len==12;for(uint32_t i=0;i<g_ed.doc.len&&i<12;i++)if(iw_doc_byte(&g_ed.doc,i)!=(uint8_t)"Keep active."[i])same=0;CHECK(same,"ops-document","active bytes unchanged");CHECK(!memcmp(&g_ed,&document_before,sizeof g_ed),"ops-document","piece table, cursor, block, dirty and reveal state unchanged"); }
static void open_ops(void)
{ fkey(F5,0);fkey(ENTER,0);fkey(DOWN,0);fkey(ENTER,0);fkey(ENTER,0); }
static void no_temp(void)
{ char hp[1024];host_name("OPS",hp);DIR *d=opendir(hp);struct dirent *e;while((e=readdir(d)))CHECK(!strstr(e->d_name,".$$"),"ops-rollback","no temporary leaked");closedir(d); }
static void alias_destinations(void)
{
    /* Ref: fat12.c parse_name83's padded empty extension, REVIEW.md P1.
     * The emulator alias gate below is the data-loss oracle; these cases
     * also cover inner/leaf components without teaching POSIX FAT rules. */
    static const char *cases[][2] = {
        { "A:\\OPS.\\ALPHA.TXT", "OPS\\ALPHA.TXT" },
        { "a:/ops./alpha.txt", "OPS\\ALPHA.TXT" },
        { "SUB.\\FRESH.", "OPS\\SUB\\FRESH" },
        { "A:\\OPS.\\SUB.\\PLAIN.", "OPS\\SUB\\PLAIN" },
        { "A:\\OPS.\\SUB.DIR\\FILE.TXT", "OPS\\SUB.DIR\\FILE.TXT" },
        { "A:\\OPS..\\ALPHA.TXT", 0 },
        { "SUB..\\FRESH", 0 },
        { "ALPHA.TXT.", 0 }
    };
    for (uint32_t i = 0; i < sizeof cases / sizeof cases[0]; i++) {
        tk('3');tks(cases[i][0]);
        int ok = lf_destination();
        CHECK(cases[i][1] ? ok && !strcmp(g_lf_dst,cases[i][1]) : !ok,
              "ops-alias",cases[i][0]);
        CHECK(!strcmp(g_name,cases[i][0]) && g_nlen==strlen(cases[i][0]),
              "ops-alias","offered input preserved after validation");
        fkey(ESC,0);
    }
    for (int op = 0; op < 2; op++) {
        int calls = creates + deletes;
        tk(op ? '8' : '3');tks("A:\\OPS.\\ALPHA.TXT");fkey(ENTER,0);
        CHECK(g_mode==M_LIST && creates+deletes==calls && content("OPS\\ALPHA.TXT","ALPHA CONTENT\r\n"),
              "ops-alias","same-file alias returns to list before Replace or mutation");
        if(g_mode==M_LFERROR)tk(' ');
    }
    active();
}
static void tests(void)
{
    tks("Keep active.");document_before=g_ed;open_ops();select_file("ALPHA.TXT");alias_destinations();tk('2'); if(!prompt("02_delete"))return;
    tk('n');CHECK(content("OPS\\ALPHA.TXT","ALPHA CONTENT\r\n"),"ops-cancel","Delete No kept selected file");
    tk('2');fkey(ENTER,0);CHECK(exists("OPS\\ALPHA.TXT"),"ops-cancel","Delete Enter defaults to No");
    tk('3');if(!prompt("03_move"))return;fkey(ESC,0);CHECK(g_mode==M_LIST,"ops-cancel","Move Escape returns to list");
    tk('8');if(!prompt("04_copy"))return;fkey(F1,0);CHECK(g_mode==M_LIST,"ops-cancel","Copy F1 returns to list");
    tk('3');tks("BETA.TXT");fkey(ENTER,0);prompt("13_move_replace");tk('n');
    CHECK(content("OPS\\BETA.TXT","BETA KEEP\r\n")&&exists("OPS\\ALPHA.TXT"),"ops-collision","Move No preserves both files");
    tk('8');tks("BETA.TXT");fkey(ENTER,0);prompt("15_copy_replace");tk('n');
    CHECK(content("OPS\\BETA.TXT","BETA KEEP\r\n"),"ops-collision","Copy No preserves target");
    tk('8');tks("COPY.TXT");fkey(ENTER,0);CHECK(content("OPS\\COPY.TXT","ALPHA CONTENT\r\n"),"ops-copy","copied highlighted file in listed directory");active();no_temp();
    select_file("ALPHA.TXT");tk('3');tks("BETA.TXT");fkey(ENTER,0);tk('y');
    CHECK(!exists("OPS\\ALPHA.TXT")&&content("OPS\\BETA.TXT","ALPHA CONTENT\r\n"),"ops-move","Replace Yes moves selected bytes");active();
    select_file("COPY.TXT");tk('3');tks("RENAMED.TXT");fkey(ENTER,0);
    CHECK(!exists("OPS\\COPY.TXT")&&content("OPS\\RENAMED.TXT","ALPHA CONTENT\r\n"),"ops-rename","new name uses rename");
    CHECK(!strcmp(g_lf_ent[g_lf_sel-2u].name,"RENAMED.TXT"),"ops-selection","rename follows the new name (real WP shot 33)");
    select_file("RENAMED.TXT");tk('3');tks("SUB\\MOVED.TXT");fkey(ENTER,0);
    CHECK(!exists("OPS\\RENAMED.TXT")&&content("OPS\\SUB\\MOVED.TXT","ALPHA CONTENT\r\n"),"ops-move","cross-directory move");
    select_file("BETA.TXT");tk('2');tk('y');CHECK(!exists("OPS\\BETA.TXT")&&exists("OPS\\LOCK.TXT"),"ops-delete","confirmed delete removes only selected file");active();
    select_file("LOCK.TXT");tk('2');tk('y');CHECK(content("OPS\\LOCK.TXT","LOCK KEEP\r\n")&&protected_attempts==0,"ops-protect","read-only delete refused before mutation");tk(' ');
    tk('3');tks("OTHER.TXT");fkey(ENTER,0);CHECK(content("OPS\\LOCK.TXT","LOCK KEEP\r\n")&&protected_attempts==0,"ops-protect","read-only move refused");if(g_mode==M_LFERROR)tk(' ');fkey(F1,0);
    /* Copy from protected source is allowed; replace protected destination is not. */
    open_ops();select_file("LOCK.TXT");tk('8');tks("READ.TXT");fkey(ENTER,0);CHECK(content("OPS\\READ.TXT","LOCK KEEP\r\n"),"ops-copy","copy read-only source");
    select_file("READ.TXT");tk('8');tks("LOCK.TXT");fkey(ENTER,0);tk('y');CHECK(content("OPS\\LOCK.TXT","LOCK KEEP\r\n")&&protected_attempts==0,"ops-protect","protected target unchanged");if(g_mode==M_LFERROR)tk(' ');
    /* Partial writes, a full disk, read failure and close failure keep both files. */
    for(int fault=0;fault<5;fault++) {
        select_file("READ.TXT");seed("OPS\\DEST.TXT","DEST KEEP");tk('8');tks("DEST.TXT");fkey(ENTER,0);
        budget=fault==0?3:-1;fail_read=fault==1;fail_close=fault==2||fault==4;fail_close_handle=fault==4?5:0;m_write_limit=fault==3?2:0;m_read_limit=3;
        tk('y');budget=-1;fail_read=fail_close=fail_close_handle=0;m_write_limit=m_read_limit=0;
        CHECK(content("OPS\\READ.TXT","LOCK KEEP\r\n"),"ops-failure","source survives copy fault");
        CHECK(content("OPS\\DEST.TXT",fault==3?"LOCK KEEP\r\n":"DEST KEEP"),"ops-failure","target commits only complete copy");
        no_temp();if(g_mode==M_LFERROR)tk(' ');
    }
    select_file("READ.TXT");tk('8');tks("NEW.TXT");fkey(ENTER,0);CHECK(content("OPS\\NEW.TXT","LOCK KEEP\r\n"),"ops-copy","new file visible after refresh");
    select_file("READ.TXT");tk('8');tks("READ.TXT");fkey(ENTER,0);if(g_mode!=M_LIST)tk('y');CHECK(content("OPS\\READ.TXT","LOCK KEEP\r\n"),"ops-self","copy to self safe");if(g_mode==M_LFERROR)tk(' ');
    int calls=creates+deletes;g_lf_sel=0;tk('8');fkey(F1,0);CHECK(creates+deletes==calls,"ops-directory","current directory never copied");
    active();
    /* More than either editor bank; repeated short transfers must copy ALL
     * bytes. A selected non-document is still an ordinary file operand. */
    char hp[1024];host_name("OPS\\BIG.DAT",hp);FILE *f=fopen(hp,"wb");
    CHECK(f!=0,"ops-large","large source created");
    if(f){for(int i=0;i<100123;i++)fputc('A'+i%26,f);fclose(f);}
    open_ops();select_file("BIG.DAT");m_read_limit=37;m_write_limit=19;
    tk('8');tks("LARGE.DAT");fkey(ENTER,0);m_read_limit=m_write_limit=0;
    CHECK(same_file("OPS\\BIG.DAT","OPS\\LARGE.DAT"),"ops-large","copy beyond BANK is byte-exact");
    CHECK(g_lf_files>=6,"ops-refresh","listing contains the new file");active();
    select_file("BIG.DAT");budget=100;tk('8');tks("FAIL.DAT");fkey(ENTER,0);
    CHECK(prompt("29_full_copy"),"ops-full","minted full-disk retry prompt");
    CHECK(!exists("OPS\\FAIL.DAT")&&file_size("OPS\\BIG.DAT")==100123,"ops-full","failed new copy leaves no destination and keeps source");
    no_temp();budget=-1;fkey(F1,0);
    /* An occupied temporary is somebody else's file. It is never truncated. */
    seed("OPS\\COLLIDE.$$$","KEEP TEMP");select_file("READ.TXT");
    tk('8');tks("COLLIDE.TXT");fkey(ENTER,0);
    CHECK(content("OPS\\COLLIDE.$$$","KEEP TEMP")&&content("OPS\\COLLIDE.TXT","LOCK KEEP\r\n"),"ops-collision","occupied temporary preserved");
    active();
    /* The longest Toolbox path still offers A:\ plus its whole name.
     * Drive characters must never overwrite the prompt's length/state. */
    char dir[128]="OPS\\", source[128], dest[128];
    for(int i=0;i<12;i++) {
        strcat(dir,"ABCDEFGH");host_name(dir,hp);mkdir(hp,0700);strcat(dir,"\\");
    }
    strcat(dir,"XY");host_name(dir,hp);mkdir(hp,0700);strcat(dir,"\\");
    strcpy(source,dir);strcat(source,"FILELONG.TXT");
    strcpy(dest,dir);strcat(dest,"NEW.TXT");seed(source,"LONG PATH KEEP");
    lf_open(dir,2u);paint_all();select_file("FILELONG.TXT");tk('3');
    CHECK(g_nlen==130&&g_nlen<sizeof g_name&&g_fresh,"ops-long-path","whole absolute offered name fits without corrupting prompt state");
    tks("NEW.TXT");fkey(ENTER,0);
    CHECK(!exists(source)&&content(dest,"LONG PATH KEEP"),"ops-long-path","maximum-length source renames safely");active();
    select_file("NEW.TXT");tk('8');tks("A:\\");fkey(ENTER,0);
    CHECK(content("NEW.TXT","LONG PATH KEEP")&&exists(dest),"ops-root","existing root directory keeps the source leaf name");active();
}

/* Reconstruct actual DRAWCELLS output between delivered keys. Required
 * prompts are matched in order against independent WP rows, never grep
 * fragments. Both emulator traces finish on the unchanged editing screen. */
static int wanted_row(const char *shot, char out[SCR_W + 1])
{
    char path[512], line[512];
    snprintf(path, sizeof path, "%s/%s.txt", grids, shot);
    FILE *f = fopen(path, "r");
    if (!f) return 0;
    while (fgets(line, sizeof line, f)) if (!strncmp(line, "24|", 3)) {
        memcpy(out, line + 3, SCR_W); out[SCR_W] = 0; fclose(f); return 1;
    }
    fclose(f); return 0;
}
static void serial_test(const char *path, int full)
{
    static const char *normal[] = { "02_delete", "02_delete", "03_move", "04_copy",
        "13_move_replace", "15_copy_replace", "04_copy", "13_move_replace", "13_move_replace" };
    static const char *disk_full[] = { "15_copy_replace", "29_full_copy", "29_full_copy", "13_move_replace", "29_full_copy" };
    const char **shots = full ? disk_full : normal;
    int count = full ? 5 : 9, matched = 0, up = 0, keys = 0;
    char line[8192], expected[SCR_W + 1];
    FILE *f = fopen(path, "r");
    CHECK(f != 0, "ops-serial", "serial capture readable");
    if (!f) return;
    for (int i = 0; i < SCR_H; i++) { memset(m_scr[i], '?', SCR_W); m_scr[i][SCR_W] = 0; }
    while (fgets(line, sizeof line, f)) {
        if (strstr(line, "TENANT-REGISTER ok app=WORD")) up = 1;
        if (!up) continue;
        if (!strncmp(line, "TENANT-EVT what=3", 17)) {
            keys++;
            if (matched < count && wanted_row(shots[matched], expected) && !memcmp(m_scr[23], expected, SCR_W)) {
                CHECK(prompt(shots[matched]), "ops-serial", "mint prompt after actual delivered key"); matched++;
            }
        }
        if (!strncmp(line, "TENANT-GATE ax=0x0031 win=1 ", 28)) { (void)tbx_fill_rect(1,0,0,0,0,0); continue; }
        if (!strncmp(line, "TENANT-GATE ax=0x0033 win=1 x=", 30)) {
            unsigned x,y,fg,bg;char *s=strstr(line," s=\""),*end=s?strstr(s,"\" fg="):0;
            if (!s || !end || sscanf(line+30,"%u y=%u",&x,&y)!=2 || sscanf(end,"\" fg=%u bg=%u",&fg,&bg)!=2) {
                CHECK(0,"ops-serial","DRAWCELLS parses");continue;
            }
            *end=0;(void)tbx_draw_cells(1,(int32_t)x,(int32_t)y,s+4,fg,bg);
        }
    }
    fclose(f);
    if (matched != count) fprintf(stderr,"  ops-serial matched %d/%d required prompts, next %s\n",matched,count,matched<count?shots[matched]:"none");
    CHECK(up && keys > 20, "ops-serial", "WORD registered and received trace");
    CHECK(matched == count, "ops-serial", "every required real-WP prompt appeared in order");
    CHECK(row_is(0,"Keep active."), "ops-serial", "active document text unchanged at end");
    printf("listfiles-ops serial: %d keys, %d/%d real WP prompts\n",keys,matched,count);
}
int main(int argc,char **argv)
{
    static int counters[2];g_ctr=counters;
    if (argc == 4) {
        grids=argv[3];serial_test(argv[2],!strcmp(argv[1],"--full-serial"));
        if(counters[1])fprintf(stderr,"RED-REASON listfiles-ops: emulator vs real WP prompts/document\n");
        return counters[1]?1:0;
    }
    if(argc!=3)return 2;
    m_dir=argv[1];grids=argv[2];
    (void)m_dirents;(void)m_ndirents;
    char hp[1024];host_name("OPS",hp);mkdir(hp,0700);host_name("OPS\\SUB",hp);mkdir(hp,0700);
    seed("OPS\\ALPHA.TXT","ALPHA CONTENT\r\n");seed("OPS\\BETA.TXT","BETA KEEP\r\n");seed("OPS\\LOCK.TXT","LOCK KEEP\r\n");
    tbx_host_reset();m_clock=(cp_time_t){1992,3,1,9,0,0,0};m_free=1000000;if(tbx_app_main())return 2;paint_all();tests();
    printf("test-iword-listfiles-ops: %d checks, %d failures\n",counters[0],counters[1]);
    if(counters[1])fprintf(stderr,"RED-REASON listfiles-ops: selected-file prompt or safety contract\n");
    return counters[1]?1:0;
}
